        mockMvc.perform(get("/api/frames/{frameId}/history", "history-no-op"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$", hasSize(1)))
            .andExpect(jsonPath("$[0].eventType").value("CREATED"));
    }

    @Test
