170:            value(record, "environment"),
171:            value(record, "status"),
172:            value(record, "status_reason"),
173:            new LocationDto(
174:                value(record, "postcode"),
175:                value(record, "postcode_area"),
176:                value(record, "postcode_district"),
177:                value(record, "postcode_sector"),
178:                value(record, "postcode_unit"),
179:                value(record, "address"),
180:                value(record, "region"),
181:                value(record, "country_code"),
182:                value(record, "town"),
183:                decimal(record, "longitude"),
184:                decimal(record, "latitude"),
185:                integer(record, "distance_to_closest_school"),
186:                value(record, "location"),
187:                value(record, "location_id")
188:            ),
189:            new SiteDto(
190:                value(record, "site_no"),
191:                value(record, "inventory_site_no"),
192:                value(record, "panel_number"),
193:                value(record, "station"),
194:                value(record, "airport")
195:            ),
196:            new TechnicalDto(
197:                value(record, "illumination_type_id"),
198:                integer(record, "number_of_slots"),
199:                value(record, "size_code"),
200:                value(record, "size_group_code"),
201:                value(record, "aspect_ratio_code"),
202:                value(record, "t_size"),
203:                integer(record, "pixel_height"),
204:                integer(record, "pixel_width")
205:            ),
206:            new CommercialDto(
207:                decimal(record, "impact_weight"),
208:                value(record, "production_rate_card"),
209:                value(record, "production_rate_card_legacy"),
210:                value(record, "pricing_grade"),
211:                value(record, "price_entity_id"),
212:                bool(record, "premium")
213:            ),
214:            new IntegrationDto(
215:                value(record, "broadsign_display_unit_id"),
216:                value(record, "broadsign_frame_id"),
217:                value(record, "broadsign_domain_id"),
218:                value(record, "linked_frame_ids")
219:            )
220:        );
221:    }
