83:    private FrameResponse createFrame(
84:        CreateFrameRequest request,
85:        HistoryEventType eventType,
86:        HistorySource source
87:    ) {
88:        if (repository.existsById(request.frameId())) {
89:            throw new DuplicateFrameException(request.frameId());
90:        }
91:
92:        Instant occurredAt = now();
93:        Frame frame = mapper.toNewEntity(request, toLocalDateTime(occurredAt));
94:        Frame saved;
95:        try {
96:            saved = repository.saveAndFlush(frame);
97:        } catch (DataIntegrityViolationException exception) {
98:            if (isDuplicateKey(exception)) {
99:                throw new DuplicateFrameException(request.frameId());
100:            }
101:            throw exception;
102:        }
103:        entityManager.refresh(saved);
104:        historyRepository.saveAndFlush(new FrameHistory(
105:            saved,
106:            eventType,
107:            occurredAt,
108:            source,
109:            Map.of()
110:        ));
111:        return mapper.toResponse(saved);
112:    }
