64:    public FrameCsvImportSummary importCsv(MultipartFile file) {
65:        List<CSVRecord> records = parse(file);
66:        Set<String> seenFrameIds = new HashSet<>();
67:        List<FrameCsvImportError> errors = new ArrayList<>();
68:        int created = 0;
69:        int duplicates = 0;
70:        int failed = 0;
71:
72:        for (CSVRecord record : records) {
73:            long rowNumber = record.getRecordNumber() + 1;
74:            String frameId = value(record, "frame_id");
75:
76:            if (frameId != null && !seenFrameIds.add(frameId)) {
77:                duplicates++;
78:                errors.add(new FrameCsvImportError(
79:                    rowNumber,
80:                    frameId,
81:                    "frameId appears more than once in the CSV"
82:                ));
83:                continue;
84:            }
85:
86:            try {
87:                CreateFrameRequest request = toRequest(record);
88:                validate(request);
89:                frameService.createImportedFrame(request);
90:                created++;
91:            } catch (DuplicateFrameException exception) {
92:                duplicates++;
93:                errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
94:            } catch (RowImportException exception) {
95:                failed++;
96:                errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
97:            } catch (DataAccessException exception) {
98:                failed++;
99:                errors.add(new FrameCsvImportError(rowNumber, frameId, "Frame could not be persisted"));
100:            }
101:        }
102:
103:        return new FrameCsvImportSummary(records.size(), created, duplicates, failed, errors);
104:    }
