106:    private List<CSVRecord> parse(MultipartFile file) {
107:        if (file == null || file.isEmpty()) {
108:            throw new InvalidCsvFileException("CSV file is empty");
109:        }
110:
111:        String content = decode(file);
112:        if (content.startsWith("\uFEFF")) {
113:            content = content.substring(1);
114:        }
115:        if (content.isBlank()) {
116:            throw new InvalidCsvFileException("CSV file is empty");
117:        }
118:
119:        try (CSVParser parser = CSV_FORMAT.parse(new StringReader(content))) {
120:            Map<String, Integer> headers = parser.getHeaderMap();
121:            Set<String> missingHeaders = REQUIRED_HEADERS.stream()
122:                .filter(header -> !headers.containsKey(header))
123:                .collect(Collectors.toCollection(java.util.TreeSet::new));
124:            if (!missingHeaders.isEmpty()) {
125:                throw new InvalidCsvFileException(
126:                    "CSV is missing required headers: " + String.join(", ", missingHeaders)
127:                );
128:            }
129:
130:            List<CSVRecord> records = parser.getRecords();
131:            if (records.isEmpty()) {
132:                throw new InvalidCsvFileException("CSV contains no data rows");
133:            }
134:            for (CSVRecord record : records) {
135:                if (record.size() != headers.size()) {
136:                    throw new InvalidCsvFileException(
137:                        "CSV row " + (record.getRecordNumber() + 1)
138:                            + " has a different number of columns than the header"
139:                    );
140:                }
141:            }
142:            return records;
143:        } catch (InvalidCsvFileException exception) {
144:            throw exception;
145:        } catch (IOException | UncheckedIOException | IllegalArgumentException exception) {
146:            throw new InvalidCsvFileException("CSV content is malformed", exception);
147:        }
148:    }
