142:        Map<String, FieldChange> changes = changedFields(existing, replacement);
143:        if (changes.isEmpty()) {
144:            return mapper.toResponse(existing);
145:        }
146:
147:        Frame saved = repository.saveAndFlush(replacement);
148:        entityManager.refresh(saved);
149:        historyRepository.save(new FrameHistory(
150:            saved,
151:            HistoryEventType.UPDATED,
152:            occurredAt,
153:            HistorySource.MANUAL,
154:            changes
155:        ));
156:        return mapper.toResponse(saved);
157:    }
