118:    private Sort parseSort(String value) {
119:        String[] parts = value.split(",", -1);
120:        if (parts.length != 2 || !SORT_FIELDS.contains(parts[0])) {
121:            throw new InvalidFrameRequestException("sort must use an allowed field and direction");
122:        }
123:
124:        Sort.Direction direction;
125:        try {
126:            direction = Sort.Direction.valueOf(parts[1].toUpperCase(Locale.ROOT));
127:        } catch (IllegalArgumentException exception) {
128:            throw new InvalidFrameRequestException("sort direction must be asc or desc");
129:        }
130:
131:        Sort primary = Sort.by(direction, parts[0]);
132:        return "frameId".equals(parts[0]) ? primary : primary.and(Sort.by("frameId"));
133:    }
