150:    private String decode(MultipartFile file) {
151:        try {
152:            byte[] bytes = file.getBytes();
153:            return StandardCharsets.UTF_8.newDecoder()
154:                .onMalformedInput(CodingErrorAction.REPORT)
155:                .onUnmappableCharacter(CodingErrorAction.REPORT)
156:                .decode(ByteBuffer.wrap(bytes))
157:                .toString();
158:        } catch (CharacterCodingException exception) {
159:            throw new InvalidCsvFileException("CSV content is not valid UTF-8", exception);
160:        } catch (IOException exception) {
161:            throw new InvalidCsvFileException("CSV file could not be read", exception);
162:        }
163:    }
